-- Metadata/counts only, run with Management API read_only=true.
select json_build_object(
 'read_only',current_setting('transaction_read_only'),
 'server_version',current_setting('server_version'),
 'auth_users',(select count(*) from auth.users),
 'vault_secrets',(select count(*) from vault.secrets),
 'hq_objects',(select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='hq_private' or (n.nspname='public' and c.relname like 'hq_%')),
 'history_exists',to_regclass('supabase_migrations.schema_migrations') is not null,
 'extensions',(select json_agg(json_build_object('name',extname,'version',extversion,'schema',extnamespace::regnamespace) order by extname) from pg_extension),
 'roles',(select json_agg(json_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'login',rolcanlogin,'bypass_rls',rolbypassrls) order by rolname) from pg_roles),
 'memberships',(select json_agg(json_build_object('role',roleid::regrole,'member',member::regrole,'admin',admin_option) order by roleid::regrole::text,member::regrole::text) from pg_auth_members),
 'schemas',(select json_agg(json_build_object('name',nspname,'owner',nspowner::regrole,'acl',nspacl) order by nspname) from pg_namespace where nspname !~ '^pg_' and nspname<>'information_schema'),
 'tables',(select json_agg(json_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',c.relowner::regrole,'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','vault','storage','hq_private','supabase_migrations') and c.relkind in ('r','p','v','S')),
 'columns',(select json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'ordinal',a.attnum,'acl',a.attacl,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in ('public','auth','vault','storage','hq_private','supabase_migrations') and c.relkind in ('r','p','v') and a.attnum>0 and not a.attisdropped),
 'constraints',(select json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated) order by n.nspname,c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','vault','storage','hq_private')),
 'indexes',(select json_agg(json_build_object('schema',schemaname,'table',tablename,'name',indexname,'definition',indexdef) order by schemaname,tablename,indexname) from pg_indexes where schemaname in ('public','auth','vault','storage','hq_private')),
 'triggers',(select json_agg(json_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','auth','vault','storage','hq_private')),
 'functions',(select json_agg(json_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'owner',p.proowner::regrole,'acl',p.proacl,'security_definer',p.prosecdef,'config',p.proconfig) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','auth','vault','hq_private')),
 'policies',(select json_agg(p order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('public','auth','vault','storage','hq_private')),
 'default_privileges',(select json_agg(json_build_object('role',defaclrole::regrole,'schema',case when defaclnamespace=0 then '' else defaclnamespace::regnamespace::text end,'type',defaclobjtype,'acl',defaclacl) order by defaclrole::regrole::text,case when defaclnamespace=0 then '' else defaclnamespace::regnamespace::text end,defaclobjtype) from pg_default_acl),
 'counts',(select json_agg(json_build_object('schema',n.nspname,'table',c.relname,'count',((xpath('/row/n/text()',query_to_xml(format('select count(*) n from %I.%I',n.nspname,c.relname),false,true,'')))[1]::text)::bigint) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','auth','vault','storage','hq_private','supabase_migrations') and c.relkind in ('r','p')),
 'vault_browser_denials',(select json_agg(json_build_object('role',r,'usage',has_schema_privilege(r,'vault','USAGE'),'ciphertext',has_table_privilege(r,'vault.secrets','SELECT'),'decrypted',has_table_privilege(r,'vault.decrypted_secrets','SELECT'))) from unnest(array['anon','authenticated']) r)
) metadata;
